'use strict';
const $=id=>document.getElementById(id);
let config=null,state=null,seeds=[],results=[],ratings={},busy=false,mode='demo',study=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
function error(message){$('error').textContent=message;$('error').hidden=false;}
async function perform(fn){if(busy)return;busy=true;$('error').hidden=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);$('status').textContent='Working…';try{await fn();}catch(e){error(e.message);}finally{busy=false;$('status').textContent='';if(state)render();else setup();}}
function panel(){const live=state?.source==='qloo-live';$('modebadge').textContent=live?'Live Qloo · Experimental model':'Research preview · Synthetic data';$('notice').textContent=live?'Recommendations use retrieved Qloo rankings. Model weights are experimental, not calibrated probabilities of your enjoyment.':'This demo uses invented taste profiles and film affinities. No live Qloo data or proven recommendation improvement yet.';$('footerstatus').textContent=config?.live_available?'Server configured for Qloo access':'Qloo integration awaiting API access';}
function setup(){panel();$('stage').textContent='01 / START WITH WHAT YOU LOVE';$('counter').textContent='Up to 3 questions';$('weights').replaceChildren();$('journal').innerHTML='<li>Ready to collect taste signals.</li>';$('download').disabled=true;$('content').innerHTML=`<h2>Your taste is the starting point.</h2><p class="support">Try the sample experience, or connect real favorites when Qloo access is configured.</p><div class="modechoices"><label><input type="radio" name="mode" value="demo" ${mode==='demo'?'checked':''}> Explore the sample</label><label><input type="radio" name="mode" value="live" ${mode==='live'?'checked':''} ${config?.live_available?'':'disabled'}> Live Qloo ${config?.live_available?'':'(awaiting access)'}</label></div><div id="liveinputs" ${mode==='live'?'':'hidden'}><label for="kind">Search category</label><select id="kind"><option value="movie">Movies</option><option value="artist">Music artists</option><option value="book">Books</option></select><label for="query">A favorite title or artist</label><div class="searchline"><input id="query" maxlength="200" placeholder="Search a favorite…"><button id="search" class="primary">Search</button></div><div id="searchresults"></div><p class="support">Confirm 2–4 favorites. Separate Qloo rankings become competing anchors for discovery.</p><ul id="seeds"></ul></div><label class="study"><input id="study" type="checkbox" ${study?'checked':''}> Optional research preview: randomly assign a question strategy</label><p class="privacy">Sessions expire after one hour; inactive records are periodically cleared from server memory. All sessions disappear when the server restarts. No account or personal details needed. Ratings stay in this page until you export them; nothing is sent to a research database.</p><button class="primary" id="begin">Start discovering ↗</button>`;document.querySelectorAll('input[name=mode]').forEach(r=>r.onchange=()=>{mode=r.value;$('liveinputs').hidden=mode!=='live';});$('study').onchange=()=>{study=$('study').checked;};$('search').onclick=()=>{const query=$('query').value,kind=$('kind').value;perform(async()=>{results=(await api('search',{query,kind})).results;if(!results.length)error('No matching entities found. Try another title or spelling.');});};$('begin').onclick=()=>perform(async()=>{state=await api('session',{mode,seeds:seeds.map(s=>s.entity_id),study});ratings={};});drawSearch();}
function drawSearch(){$('searchresults').replaceChildren();results.forEach(item=>{const b=document.createElement('button');b.className='searchresult';b.textContent=`${item.name} · ${item.kind}`;b.disabled=seeds.length>=4||seeds.some(s=>s.entity_id===item.entity_id);b.onclick=()=>{seeds.push(item);drawSearch();};$('searchresults').append(b);});$('seeds').replaceChildren();seeds.forEach(item=>{const li=document.createElement('li'),b=document.createElement('button');b.className='textbutton';b.textContent=`Remove ${item.name}`;b.onclick=()=>{seeds=seeds.filter(s=>s!==item);drawSearch();};li.append(document.createTextNode(item.name+' '),b);$('seeds').append(li);});}
function sidebar(){const hidden=state.study;$('weights').innerHTML=hidden?'<p>Strategy details are hidden during the research questions.</p>':Object.entries(state.weights).map(([name,w])=>`<div class="barrow"><span>${esc(name)}</span><span>${Math.round(w*100)}%</span></div><div class="track"><div class="bar" style="width:${w*100}%"></div></div>`).join('');$('journal').replaceChildren();const rows=state.history.map(a=>`${a.name}: ${a.answer==='skip'?'unfamiliar / skipped':a.answer}.`);if(!rows.length)rows.push('Taste evidence loaded. Choosing the next step.');rows.forEach(text=>{const li=document.createElement('li');li.textContent=text;$('journal').append(li);});$('download').disabled=false;}
function render(){panel();sidebar();const q=state.next;$('counter').textContent=q.action==='ask'?`Question ${state.answered+1} of ${state.budget}`:`${state.answered} questions answered`;if(q.action!=='ask'){showResults();return;}$('stage').textContent='02 / FOLLOW YOUR CURIOSITY';const f=q.entity;$('content').innerHTML=`<h2>Would you enjoy this film?</h2><p class="support">No right answer. If you haven’t seen it or aren’t sure, choose unfamiliar.</p><article class="film"><span class="genre">${esc(f.subtitle)}</span><h3>${esc(f.name)}</h3><p>${esc(f.description)}</p></article><div class="answers"><button class="answer" data-answer="like">Yes, my kind of film</button><button class="answer" data-answer="dislike">Not for me</button><button class="answer" data-answer="skip">Unfamiliar / skip</button></div><p class="why">${state.study?'Strategy details are hidden during research questions.':`The agent selected this film to distinguish its current taste anchors. Expected model information gain: ${Number(q.model_information_gain_bits).toFixed(3)} bits.`} ${state.source==='synthetic-fixture'?'Affinities are invented for this demo.':'Based on seed-specific Qloo rankings; not a claim about why you like a film.'}</p>${previewDetails(q)}${undoButton()}<button class="textbutton" id="stop">End session and delete server data</button>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>perform(async()=>{state=await api('answer',{session_id:state.session_id,entity_id:q.entity_id,answer:b.dataset.answer});}));$('stop').onclick=reset;bindUndo();}
function showResults(){$('stage').textContent='03 / YOUR NEXT DISCOVERY';const skipped=state.history.length&&state.history.every(a=>a.answer==='skip');$('content').innerHTML=`<h2>${state.recommendations.length?'A few possibilities to explore.':'We need more shared evidence.'}</h2><p class="support">${skipped?'You skipped every question, so the model weights remain unchanged.':state.source==='synthetic-fixture'?'These are illustrative suggestions under the synthetic model.':'These suggestions combine retrieved Qloo ranks with your answers.'} ${state.recommendations.length?'Rate only films you know well enough to judge.':'Try different favorite anchors. Missing results do not mean dislike.'}</p>${state.recommendations.map((r,i)=>`<article class="result"><span>0${i+1}</span><div><h3>${esc(r.label)}</h3><p>${esc(r.entity.subtitle)}<br>${esc(r.entity.description)}</p><label class="ratinglabel" for="rating-${i}">How well does it fit your taste?</label><select class="rating" id="rating-${i}" data-rating="${esc(r.entity_id)}"><option value="">Unfamiliar / not rated</option><option value="1">1 — Poor fit</option><option value="2">2 — Slight fit</option><option value="3">3 — Mixed</option><option value="4">4 — Good fit</option><option value="5">5 — Excellent fit</option></select>${evidenceDetails(r)}</div></article>`).join('')}<p class="why">${state.study?'Rate before exporting; the assigned strategy is included in the evidence file.':esc(state.next.reason)} Asked films are excluded. Shared candidate evidence: ${state.evidence_coverage.shared_candidates}.</p>${undoButton()}<button class="primary" id="restart">Explore again ↻</button><p class="privacy">Restart deletes this session from server memory. Export first if you want a copy.</p>`;document.querySelectorAll('[data-rating]').forEach(s=>{s.value=ratings[s.dataset.rating]||'';s.onchange=()=>{if(s.value)ratings[s.dataset.rating]=Number(s.value);else delete ratings[s.dataset.rating];};});$('restart').onclick=reset;bindUndo();}

function undoButton(){return state.answered>0&&!state.study?'<button class="textbutton undo" id="undo">← Change my last answer</button>':'';}
function bindUndo(){if($('undo'))$('undo').onclick=()=>perform(async()=>{state=await api('undo',{session_id:state.session_id});ratings={};});}
function previewDetails(q){if(state.study||!q.answer_previews)return '';return `<details class="evidence"><summary>What could my answer change?</summary><p>These are possible model outputs, not predictions of what you will enjoy. Answer based on your own taste.</p>${Object.entries(q.answer_previews).map(([answer,items])=>`<h3>If you choose ${answer==='like'?'yes':'not for me'}</h3><ul>${items.map(r=>`<li>${esc(r.label)}</li>`).join('')}</ul>`).join('')}</details>`;}
function evidenceDetails(r){if(state.study)return '';const entries=Object.entries(r.evidence||{});if(!entries.length)return '';return `<details class="evidence"><summary>Why is this on my shortlist?</summary><p>${state.source==='qloo-live'?'These are the returned Qloo ranks for each favorite anchor.':'These are illustrative ranks from invented affinity profiles.'} The agent combines these signals with your answers. This does not establish why you personally like a film.</p><div class="tablewrap"><table><thead><tr><th scope="col">Anchor</th><th scope="col">Rank</th><th scope="col">Model weight</th></tr></thead><tbody>${entries.map(([anchor,e])=>`<tr><td>${esc(anchor)}</td><td>${esc(e.returned_rank)} / ${esc(e.ranking_size)}</td><td>${Math.round((state.weights[anchor]||0)*100)}%</td></tr>`).join('')}</tbody></table></div><p>All anchors returned this candidate. Missing evidence is never interpreted as dislike. Model weights are not enjoyment probabilities.</p></details>`;}

async function reset(){perform(async()=>{await api('delete',{session_id:state.session_id});state=null;seeds=[];results=[];ratings={};});}
$('download').onclick=()=>{if(!state)return;const {session_id,...evidence}=state;const payload={schema_version:1,exported_at:new Date().toISOString(),...evidence,ratings,warning:'Experimental model; synthetic sessions do not establish Qloo performance or real-user improvement.'};const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));link.href=url;link.download='tasteprobe-session.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
(async()=>{try{config=await api('config');setup();}catch(e){$('content').innerHTML='<h2>The TasteProbe server is unavailable.</h2><p class="support">Start the backend with <code>python server.py</code>, then open its printed address. This application requires the backend; a static file server cannot run discovery sessions.</p>';error('Could not connect to the session API.');}})();
